import { Product } from '@/types/product';
import { getAuthHeaders } from './utils';

export const productService = {
  getAll: async (): Promise<Product[]> => {
    const headers = await getAuthHeaders();
    const response = await fetch('/api/products', { headers });

    if (!response.ok) {
      const errorData = await response.json().catch(() => ({}));
      throw new Error(errorData.error ?? 'Failed to fetch products');
    }

    return response.json();
  },

  getByCompany: async (companyId?: string): Promise<Product[]> => {
    const headers = await getAuthHeaders();
    const search = companyId ? `?companyId=${encodeURIComponent(companyId)}` : '';
    const response = await fetch(`/api/products${search}`, { headers });

    if (!response.ok) {
      const errorData = await response.json().catch(() => ({}));
      throw new Error(errorData.error ?? 'Failed to fetch products by company');
    }

    return response.json();
  },

  getById: async (id: string): Promise<Product> => {
    const headers = await getAuthHeaders();
    const response = await fetch(`/api/products/${id}`, { headers });

    if (!response.ok) {
      const errorData = await response.json().catch(() => ({}));
      throw new Error(errorData.error ?? 'Failed to fetch product');
    }

    return response.json();
  },
};
